card_mod.style:
ha-state-icon {
  transition: color 300ms ease-in-out,
              filter 300ms ease-in-out,
              transform 180ms ease-in-out;
}
@media (prefers-reduced-motion: reduce) {
  ha-state-icon { transition: none; }
}

ha-state-icon {
  transition: color 800ms ease-in-out,
              filter 800ms ease-in-out,
              transform 180ms ease-in-out;
}
ha-card {
  box-shadow: inset 0 0 0 1000px rgba(255, 193, 7, 0);
  transition: box-shadow 800ms ease-in-out;
}
ha-card:has(ha-state-icon[data-state="on"]) {
  box-shadow: inset 0 0 0 1000px rgba(255, 193, 7, 0.09);
}
@media (prefers-reduced-motion: reduce) {
  ha-state-icon, ha-card { transition: none; }
}

